import { Component, JSX, splitProps } from 'solid-js';
import * as DiamondGridPrimitive from '@exhuma/core';

export interface DiamondGridProps extends JSX.HTMLAttributes<HTMLDivElement> {
  [key: string]: unknown;
}

export const DiamondGrid: Component<DiamondGridProps> = (props) => {
  const [local, others] = splitProps(props, ['class', 'children']);
  return (
    <DiamondGridPrimitive.DiamondGrid
      class={`flex items-center justify-center w-full max-w-6xl mx-auto py-12 overflow-hidden ${local.class ?? ''}`}
      {...others}
    >
      {local.children}
    </DiamondGridPrimitive.DiamondGrid>
  );
};

