import { DiamondGrid } from '@exhuma/core';

class ExhumaDiamondGridElement extends HTMLElement {
  connectedCallback() {
    this.classList.add('exhuma-diamond-grid');
    this.style.display = 'block';
  }
}

if (!customElements.get('exhuma-diamond-grid')) {
  customElements.define('exhuma-diamond-grid', ExhumaDiamondGridElement);
